/**
 * @method
 * @name scwin.tx_goZipCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_goZipCode = async function () {
    const sbmOptions = {
        id: "tx_goZipCode",
        method: "post",
        action: "/discls/disclosureCommon.do",
        ref: "dma_goZipCodeReq",
        target: "dlt_resultVo=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods70017.tx_goZipCode" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


