/**
 * @method
 * @name scwin.specialWord
 * @author Inswave
 * @date 2026. 09. 29
 * @param str
 * @returns
 * @hidden N
*/
scwin.specialWord = function (str) {
    /* sdd-asis-lifecycle:begin fn_SpecialWord — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const reg = /%/;
    if (str == null || str === "") {
        return false;
    }
    if (reg.test(str)) {
        return true;
    }
    /* sdd-asis-lifecycle:end */
};


